const today = new Date(); today.setHours(0,0,0,0);
const OWNER = 'Meridian Bookkeeping & Tax';
const T = {
 US: {
  1: { s: 'Friendly reminder: invoice {no} was due {due}', b: 'Hi {client},

A quick reminder that invoice {no} for {amt} was due on {due}. If you have already paid, thank you, and please ignore this note.

Thanks,
' + OWNER },
  2: { s: 'Follow-up: invoice {no} is {days} days past due', b: 'Hi {client},

Invoice {no} for {amt} is now {days} days past due. Could you let me know when we can expect payment, or reply if there is a problem with the invoice?

Thank you,
' + OWNER },
  3: { s: 'Final notice: invoice {no} ({amt})', b: 'Hello {client},

This is a final notice for invoice {no} for {amt}, now {days} days overdue. Please arrange payment within 7 days to avoid a pause on non-essential work under our fee policy.

Regards,
' + OWNER } },
 UK: {
  1: { s: 'Gentle reminder: invoice {no} fell due on {due}', b: 'Dear {client},

Just a gentle reminder that invoice {no} for {amt} fell due on {due}. If payment is already on its way, please disregard this message and thank you.

Kind regards,
' + OWNER },
  2: { s: 'Invoice {no} is now {days} days overdue', b: 'Dear {client},

Our records show invoice {no} for {amt} is {days} days overdue. We would be grateful if you could confirm a payment date, or let us know if anything needs correcting.

Kind regards,
' + OWNER },
  3: { s: 'Final reminder: invoice {no} ({amt})', b: 'Dear {client},

This is our final reminder regarding invoice {no} for {amt}, now {days} days overdue. Please arrange payment within 7 days; otherwise we may need to pause non-essential work in line with our fee policy.

Yours sincerely,
' + OWNER } } };
const sym = { USD: '$', GBP: '£' };
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (String(r.status).toLowerCase() === 'paid') continue;
  const due = new Date(r.due_date); due.setHours(0,0,0,0);
  const days = Math.floor((today - due) / 86400000);
  const tier = days >= 30 ? 3 : days >= 14 ? 2 : days >= 1 ? 1 : 0;
  const last = Number(r.last_tier_sent || 0);
  if (tier === 0 || tier <= last) continue;
  const reg = String(r.region).toUpperCase() === 'UK' ? 'UK' : 'US';
  const fill = s => s.replace(/{no}/g, r.invoice_no).replace(/{client}/g, r.client).replace(/{due}/g, r.due_date)
    .replace(/{days}/g, days).replace(/{amt}/g, (sym[r.currency] || '') + Number(r.amount).toFixed(2));
  out.push({ json: { invoice_no: r.invoice_no, to: r.email, tier, days_overdue: days,
    subject: fill(T[reg][tier].s), message: fill(T[reg][tier].b) } });
}
return out;

const today = new Date(); today.setHours(0,0,0,0);
let n = 0, tot = { USD: 0, GBP: 0 }; const lines = [];
for (const it of $input.all()) { const r = it.json; if (String(r.status).toLowerCase() === 'paid') continue;
  const d = Math.floor((today - new Date(r.due_date)) / 86400000); if (d < 1) continue; n++; tot[r.currency] = (tot[r.currency] || 0) + Number(r.amount);
  lines.push(`${r.invoice_no} | ${r.client} | ${r.currency} ${Number(r.amount).toFixed(2)} | ${d} days overdue | tier sent: ${r.last_tier_sent}`); }
const msg = `Weekly receivables summary\n\nOverdue invoices: ${n}\nOutstanding overdue: USD ${(tot.USD||0).toFixed(2)} / GBP ${(tot.GBP||0).toFixed(2)}\n\n` + lines.join('\n');
return [{ json: { subject: 'Weekly overdue invoice summary', message: msg } }];
